    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    shapes = []

    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color]
        if not cells:
            continue
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        # Components are represented by their bounding boxes.
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        box = [[grid[r][c] == color for c in range(c0, c1+1)]
               for r in range(r0, r1+1)]
        shapes.append((color, r0, r1, c0, c1, box))

    # A complete rectangular border enclosing a nonempty pattern is the stencil.
    sources = []
    for s in shapes:
        color, r0, r1, c0, c1, box = s
        border = (all(box[0]) and all(box[-1]) and
                  all(row[0] and row[-1] for row in box))
        if border:
            inside = [row[1:-1] for row in box[1:-1]]
            if any(any(row) for row in inside):
                sources.append((s, inside))

    if not sources:
        return out
    source, pattern = max(sources, key=lambda x: sum(map(sum, x[1])))
    sh, sw = len(pattern), len(pattern[0])

    for color, r0, r1, c0, c1, box in shapes:
        if (color, r0, r1, c0, c1) == source[:5]:
            continue
        # Skip incomplete outlines; these are not pattern frames.
        if not (all(box[0]) and all(box[-1]) and
                all(row[0] and row[-1] for row in box)):
            for r in range(r0, r1+1):
                for c in range(c0, c1+1):
                    out[r][c] = 0
            continue

        th, tw = r1-r0-1, c1-c0-1
        # Transfer the stencil by nearest-cell scaling.
        for i in range(th):
            for j in range(tw):
                si = min(sh-1, int((i + 0.5) * sh / th))
                sj = min(sw-1, int((j + 0.5) * sw / tw))
                if pattern[si][sj]:
                    out[r0+1+i][c0+1+j] = color

    return out
